#!/usr/bin/env bash # Omega Swarm — Production Deployment Script # Usage: ./scripts/deploy.sh [staging|production] # Requires: Railway CLI, jq set -euo pipefail ENV=${1:-staging} PROJECT_ID_STAGING=${RAILWAY_STAGING_PROJECT_ID:-} PROJECT_ID_PROD=${RAILWAY_PROD_PROJECT_ID:-} SERVICE_NAME_STAGING=omega-swarm-staging SERVICE_NAME_PROD=omega-swarm TIMESTAMP=$(date +%Y%m%d_%H%M%S) DEPLOYMENT_TAG=deploy-${TIMESTAMP} echo ============================================ echo Omega Swarm Deployment Script echo Environment: ${ENV} echo Timestamp: ${TIMESTAMP} echo ============================================ # Validate environment if [[ $ENV != staging && $ENV != production ]]; then echo Error: Environment must be 'staging' or 'production' exit 1 fi # Validate Railway CLI if ! command -v railway &> /dev/null; then echo Error: Railway CLI not found. Install with: npm install -g @railway/cli exit 1 fi # Validate token if [[ -z ${RAILWAY_TOKEN:-} ]]; then echo Error: RAILWAY_TOKEN environment variable not set exit 1 fi # Select project and service if [[ $ENV == staging ]]; then PROJECT_ID=$PROJECT_ID_STAGING SERVICE_NAME=$SERVICE_NAME_STAGING elif [[ $ENV == production ]]; then PROJECT_ID=$PROJECT_ID_PROD SERVICE_NAME=$SERVICE_NAME_PROD fi if [[ -z $PROJECT_ID ]]; then echo Error: PROJECT_ID not set for $ENV exit 1 fi echo Step 1/5: Logging in to Railway... railway login --token $RAILWAY_TOKEN echo Step 2/5: Linking project... railway link --project $PROJECT_ID echo Step 3/5: Deploying $SERVICE_NAME... railway up --service $SERVICE_NAME echo Step 4/5: Waiting for healthcheck... sleep 15 HEALTH_URL=https://$([[ $ENV == staging ]] && echo staging.ndeku.com || echo ndeku.com)/api/health if curl -sf $HEALTH_URL > /dev/null; then echo Healthcheck PASSED: $HEALTH_URL else echo Healthcheck FAILED: $HEALTH_URL exit 1 fi echo Step 5/5: Running smoke tests... curl -sf https://$([[ $ENV == staging ]] && echo staging.ndeku.com || echo ndeku.com)/api/trpc/agent.list > /dev/null || true echo echo ============================================ echo Deployment to $ENV COMPLETED echo ============================================